import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    arr = data[0]
    brr = data[1]
    ans = 0
    n = len(arr)
    m = len(brr)

    for i in range(n):
        for j in range(i, n):
            count = 0
            for k in range(n):
                if k < i or k > j:
                    if count < m:
                        if arr[k] == brr[count]:
                            count += 1
                    else:
                        break
            if count == m:
                length = j - i + 1
                if ans < length:
                    ans = length
    print(ans)

if __name__ == "__main__":
    main()

